head.script:
scwin.screenId = "jldfil70311";

///////// 1. 변수 및 선언 영역 /////////

scwin.prgIfm = $c.util.getComponent('prgIfm');


///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.upd_etnAttachExcelfile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_etnAttachExcelfile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_etnAttachExcelfile"]');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil70311.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_EtnExcelUpload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_EtnExcelUpload_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_EtnExcelUpload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.etnExcelUpload()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70311.btn_EtnExcelUpload_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_window_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_window_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_window_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70311.btn_window_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_EtnExcelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_EtnExcelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnExcelUpload",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_EtnExcelUploadReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil70311.tx_fn_EtnExcelUpload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.etnExcelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.etnExcelUpload = async function () {
    /* sdd-asis-lifecycle:begin fn_EtnExcelUpload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.etnlistPageForm || { elements: [] });
    if (($c.util.getComponent('upd_etnAttachExcelfile').getValue() == null ? '' : String($c.util.getComponent('upd_etnAttachExcelfile').getValue())) === '') {
        await $c.win.alert("파일을 업로드해주세요.");
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_etnAttachExcelfile').getValue())) {
            await $c.win.alert("엑셀파일만 업로드 해주세요.");
            return;
        }
    }
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        ($c.util.getComponent("searchFile") && $c.util.getComponent("searchFile").hide ? $c.util.getComponent("searchFile").hide() : console.warn('[sdd] hide 대상 미해결: ' + "searchFile"));
        ($c.util.getComponent("confirmBtn") && $c.util.getComponent("confirmBtn").hide ? $c.util.getComponent("confirmBtn").hide() : console.warn('[sdd] hide 대상 미해결: ' + "confirmBtn"));
        scwin.prgIfm.setStyle("display", "");
        const previewWin = (Promise.resolve($c.win.openPopup("/progress_blank_pop/progress_blank_pop.xml", { id: "progressFrm", scrollbars: true, resizable: true, width: "300", height: "50", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("progressFrm"); this.closed = true; } });
        form.action = "/etn/EtnList.do";
        $c.util.getComponent('dma_EtnExcelUploadReq').set('method', 'etnExcelUpload');
        await scwin.tx_fn_EtnExcelUpload();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileType
 * @author Inswave
 * @date 2026. 09. 29
 * @param filePath
 * @returns
 * @hidden N
*/
scwin.checkFileType = function (filePath) {
    /* sdd-asis-lifecycle:begin checkFileType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fileFormat = filePath.toLowerCase();
    if (fileFormat.indexOf(".xls") > -1) {
        return true;
    } else {
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close_pop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close_pop = function () {
    /* sdd-asis-lifecycle:begin close_pop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc(null, '/jldfil70301/jldfil70301.xml', { method: "searchList", listBzCd: "1" });
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
